__modules["core.state"] = function()
local storage = require("ttt.storage")

local S = {}

S.conn = storage.get("connection") or {}
S.conn.url = S.conn.url or "http://localhost:8080"
S.conn.client_id = S.conn.client_id or "opentdf"
S.conn.client_secret = S.conn.client_secret or ""
S.settings = storage.get("settings") or {}
S.page_size = tonumber(S.settings.page_size) or 50
S.status = "idle"
S.message = ""
S.token = nil
S.token_exp = 0
S.token_endpoint = nil
S.counts = {}
S.namespaces = {}
S.providers = {}
S.base = nil
S.panels = {}
S.lists = {}

function S.redraw()
  for _, p in pairs(S.panels) do
    pcall(p.redraw, p)
    return
  end
end

function S.configured()
  return S.conn.client_secret ~= "" and S.conn.url ~= ""
end

function S.reset_lists()
  for _, lv in pairs(S.lists) do
    lv.offset = 0
    lv.sel = 1
    lv.loaded = false
  end
end

return S
end

-- src/core/util.lua ---------------------------------------------------------
__modules["core.util"] = function()
local json = require("ttt.json")

local U = {}

function U.urlencode(s)
  local out = {}
  s = tostring(s)
  for i = 1, #s do
    local c = s:sub(i, i)
    if c:find("^[%w%-%._~]$") then
      out[#out + 1] = c
    else
      out[#out + 1] = string.format("%%%02X", string.byte(c))
    end
  end
  return table.concat(out)
end

function U.form(t)
  local parts = {}
  for k, v in pairs(t) do
    parts[#parts + 1] = U.urlencode(k) .. "=" .. U.urlencode(v)
  end
  return table.concat(parts, "&")
end

-- ttt.json encodes an empty table as an array, which protobuf rejects for a map.
function U.encode(t)
  if next(t) == nil then
    return "{}"
  end
  local s = json.encode(t)
  s = s:gsub('"labels":%[%]', '"labels":{}')
  return s
end

function U.trim(s)
  s = tostring(s or "")
  s = s:gsub("^%s+", "")
  s = s:gsub("%s+$", "")
  return s
end

function U.split(s, sep)
  local out, start = {}, 1
  s = s or ""
  while true do
    local i = s:find(sep, start, true)
    local part = U.trim(i and s:sub(start, i - 1) or s:sub(start))
    if part ~= "" then
      out[#out + 1] = part
    end
    if not i then
      break
    end
    start = i + #sep
  end
  return out
end

function U.date(ts)
  if type(ts) ~= "string" or #ts < 16 then
    return ""
  end
  return ts:sub(1, 10) .. " " .. ts:sub(12, 16)
end

function U.human(v, prefix)
  if type(v) ~= "string" or v == "" then
    return ""
  end
  if v:sub(1, #prefix) == prefix then
    v = v:sub(#prefix + 1)
  end
  v = v:gsub("_", " ")
  v = v:lower()
  return v:sub(1, 1):upper() .. v:sub(2)
end

function U.alg(v)
  if type(v) ~= "string" then
    return ""
  end
  v = v:gsub("^ALGORITHM_", "")
  v = v:gsub("_", " ")
  return v
end

function U.active(v)
  if v == false then
    return "Inactive"
  end
  return "Active"
end

function U.labels(md)
  local labels = md and md.labels
  if type(labels) ~= "table" then
    return ""
  end
  local keys = {}
  for k in pairs(labels) do
    keys[#keys + 1] = k
  end
  table.sort(keys)
  local parts = {}
  for _, k in ipairs(keys) do
    parts[#parts + 1] = k .. "=" .. tostring(labels[k])
  end
  return table.concat(parts, ", ")
end

function U.parse_labels(s)
  local labels = {}
  for _, pair in ipairs(U.split(s, ",")) do
    local i = pair:find("=", 1, true)
    if i then
      local k = U.trim(pair:sub(1, i - 1))
      if k ~= "" then
        labels[k] = U.trim(pair:sub(i + 1))
      end
    end
  end
  return labels
end

function U.host(uri)
  if type(uri) ~= "string" then
    return ""
  end
  local h = uri:gsub("^%a+://", "")
  return h
end

function U.action_names(actions)
  local names = {}
  for i, a in ipairs(actions or {}) do
    names[i] = a.name or U.human(a.standard, "STANDARD_ACTION_"):lower()
  end
  return table.concat(names, ", ")
end

function U.option_label(options, value)
  for _, o in ipairs(options) do
    if o.value == value then
      return o.label
    end
  end
  return "Select…"
end

function U.created(x)
  return U.date(x.metadata and x.metadata.createdAt)
end

function U.updated(x)
  return U.date(x.metadata and x.metadata.updatedAt)
end

function U.rule(a)
  return U.human(a.rule, "ATTRIBUTE_RULE_TYPE_ENUM_")
end

function U.inactive_style(x)
  return x.active == false and "muted" or "default"
end

-- Bound arguments come first, then the caller's.
function U.bind(fn, ...)
  local bound = { n = select("#", ...), ... }
  return function(...)
    local n = select("#", ...)
    local args = { unpack(bound, 1, bound.n) }
    for i = 1, n do
      args[bound.n + i] = select(i, ...)
    end
    return fn(unpack(args, 1, bound.n + n))
  end
end

return U
end

