__modules["features.kas.key_page"] = function()
local U = require("core.util")
local UI = require("components")
local Store = require("features.kas.store")
local Commands = require("features.kas.commands")

local M = {}

local function actions(kk, h, tab)
  h:button({ label = "Rotate", on_click = U.bind(Commands.key, tab, "rotate", kk) })
