__modules["shared.entity"] = function()
local U = require("core.util")
local S = require("core.state")
local UI = require("components")

-- The entity picker and request shape shared by Entitlements and Decision.
local M = {}

M.TYPES = {
  { label = "Client ID", value = "clientId" },
  { label = "Email", value = "emailAddress" },
  { label = "Username", value = "userName" },
  { label = "JWT", value = "jwt" },
  { label = "This connection's token", value = "request" },
}

M.HINTS = {
  clientId = "opentdf",
  emailAddress = "alice@example.com",
  userName = "alice",
  jwt = "eyJhbGciOi…",
  request = "uses the token of the configured client",
}

function M.new()
  return { kind = "clientId", value = "opentdf" }
end

function M.identifier(entity)
  if entity.kind == "request" then
    return { withRequestToken = true }
  end
  local value = U.trim(entity.value)
  if entity.kind == "jwt" then
    return { token = { ephemeralId = "jwt", jwt = value } }
  end
  local e = { ephemeralId = "entity", category = "CATEGORY_SUBJECT" }
  e[entity.kind] = value
  return { entityChain = { ephemeralId = "chain", entities = { e } } }
end

function M.label(entity)
  if entity.kind == "request" then
    return "client " .. S.conn.client_id .. " (request token)"
  end
  if entity.kind == "jwt" then
    return "the pasted JWT"
  end
  return U.option_label(M.TYPES, entity.kind):lower() .. " " .. U.trim(entity.value)
end

-- Sets st.err and returns true when st.entity has no value to send.
function M.missing(st)
  if st.entity.kind ~= "request" and U.trim(st.entity.value) == "" then
    st.err = "Enter an entity first"
    S.redraw()
    return true
  end
  return false
end

local function set_kind(entity, kind)
  if kind ~= entity.kind then
    entity.kind = kind
    entity.value = kind == "clientId" and S.conn.client_id or ""
  end
  S.redraw()
end

local function set_value(entity, text)
  entity.value = text
end

local function kind_picker(entity, b)
  UI.dropdown(b, M.TYPES, entity.kind, U.bind(set_kind, entity))
end

local function request_hint(b)
  b:label({ text = M.HINTS.request, style = "muted", padding_left = 1 })
end

function M.fields(h, entity, on_submit)
  UI.frame(h, "Entity", U.bind(kind_picker, entity), { width = 28 })
  if entity.kind == "request" then
    UI.frame(h, "Value", request_hint)
    return
  end
  h:input({
    border = true,
    title = U.option_label(M.TYPES, entity.kind),
    value = entity.value,
    placeholder = M.HINTS[entity.kind],
    on_change = U.bind(set_value, entity),
    on_submit = on_submit,
  })
end

return M
end

-- src/shared/namespace_actions.lua ------------------------------------------
__modules["shared.namespace_actions"] = function()
local U = require("core.util")
local S = require("core.state")
local SVC = require("core.services")
local Api = require("core.api")
local Actions = require("features.actions.store")

-- Action names by namespace, for forms that pair actions with attribute
-- values: every namespace has its own standard and custom actions.
local M = {}

local cache = {}

function M.namespace_id(fqn)
  local host = type(fqn) == "string" and fqn:match("^%a+://([^/]+)")
  for _, ns in ipairs(S.namespaces) do
    if ns.label == host then
      return ns.value
    end
  end
  return nil
end

local function loaded(ns_id, err, data)
  local names, seen = {}, {}
  for _, a in ipairs(err and {} or Actions.extract(data)) do
    if a.name and not seen[a.name] then
      seen[a.name] = true
      names[#names + 1] = a.name
    end
  end
  cache[ns_id] = { names = names, err = err }
  S.redraw()
end

-- The namespace's action names, or nil while they load; err when they failed.
function M.names(ns_id)
  if not ns_id then
    return nil
  end
  local entry = cache[ns_id]
  if entry == nil then
    cache[ns_id] = false
    Api.call(SVC.ACT .. "ListActions", { namespaceId = ns_id, pagination = { limit = 1000 } }, U.bind(loaded, ns_id))
    return nil
  end
  if entry == false then
    return nil
  end
  return entry.names, entry.err
end

function M.forget()
  cache = {}
end

return M
end

-- src/shared/policy.lua -----------------------------------------------------
__modules["shared.policy"] = function()
local U = require("core.util")
local S = require("core.state")
local UI = require("components")

-- Pieces shared by the namespace, attribute and value screens.
local M = {}

M.LABELS_HINT = "owner=security, env=dev"

local function labels_saved(item, labels, after)
  item.metadata = item.metadata or {}
  item.metadata.labels = labels
  if after then
    after()
  end
end

local function save_labels(item, path, after, v, done)
  local labels = U.parse_labels(v.labels)
  local req = { id = item.id, metadata = { labels = labels }, metadataUpdateBehavior = "METADATA_UPDATE_ENUM_REPLACE" }
  UI.save(path, req, done, U.bind(labels_saved, item, labels, after))
end

function M.labels_dialog(what, item, path, after)
  UI.dialog({
    title = "Edit Labels · " .. what,
    submit = "Save",
    fields = {
      { key = "labels", label = "Labels", value = U.labels(item.metadata), placeholder = M.LABELS_HINT },
    },
    on_submit = U.bind(save_labels, item, path, after),
  })
end

-- Labels and Deactivate buttons for a detail page's title row; command gets
-- (cmd, item).
function M.actions(h, item, command)
  h:button({ label = "Labels", on_click = U.bind(command, "labels", item) })
  if item.active ~= false then
    h:button({ label = "Deactivate", on_click = U.bind(command, "deactivate", item) })
  end
end

local function namespaces()
  return S.namespaces
end

function M.namespace_field(ns)
  if (not ns or ns == "") and S.namespaces[1] then
    ns = S.namespaces[1].value
  end
  return { key = "namespace", label = "Namespace", kind = "enum", value = ns, options = namespaces }
end

return M
end

-- src/shared/value_picker.lua -----------------------------------------------
__modules["shared.value_picker"] = function()
local ttt = require("ttt")
local U = require("core.util")
local S = require("core.state")
local SVC = require("core.services")
local Api = require("core.api")
local UI = require("components")

-- A dialog that searches attributes and lists their values, paged on the
-- client so each page shows values rather than attributes.
local M = {}

local COLUMNS = { { label = "Attribute value" }, { label = "Rule", width = 9 } }

local last_search = ""

local function fetched(lv, gen, err, data)
  if gen ~= lv.gen then
    return
  end
  lv.loading = false
  lv.err = err
  local out = {}
  for _, a in ipairs((data and data.attributes) or {}) do
    for _, v in ipairs(a.values or {}) do
      out[#out + 1] = { id = v.id, fqn = v.fqn, rule = U.rule(a) }
    end
  end
  lv.all = out
  lv.offset = 0
  lv.sel = 1
  UI.slice(lv)
  S.redraw()
end

local function fetch(lv)
  lv.gen = lv.gen + 1
  lv.loading = true
  local req = { pagination = { limit = 100 } }
  if lv.search ~= "" then
    req.search = { term = lv.search }
  end
  Api.call(SVC.ATTR .. "ListAttributes", req, U.bind(fetched, lv, lv.gen))
end

local function search(lv)
  last_search = lv.search
  fetch(lv)
end

local function row(r)
  return { r.fqn, r.rule }
end

local function choose(on_pick, r)
  ttt.close_dialog()
  on_pick(r.fqn, r.id)
end

local function body(lv, on_pick, hint, p)
  UI.search(p, lv, "Search attributes, e.g. acme or department…", U.bind(search, lv))
  UI.table(p, lv, {
    frame = "Attribute values",
    noun = "values",
    empty = "No attribute values match",
    columns = COLUMNS,
    row = row,
    on_open = U.bind(choose, on_pick),
  })
  p:label({ text = hint, style = "muted" })
end

-- on_pick receives the value's FQN and ID.
function M.open(on_pick, title, hint)
  local lv = UI.list("picker", { client = true })
  lv.search = last_search
  fetch(lv)
  hint = hint or "Enter or double-click adds the value."
  UI.open_dialog(title or "Add Attribute Value", 96, 26, U.bind(body, lv, on_pick, hint))
end

return M
end

require("main")
